import java.util.Arrays;

/**
 * Tiny CPH-style judge for the generated LeetCode scaffolds. Generated by leet.py.
 *
 * @author Timothy Julian
 */
public class Judge {

    private int n = 0;
    private int bad = 0;

    /** Compare one result against the expected value scraped from the problem statement. */
    public void check(String want, Object got) {
        n++;
        String s = show(got);
        boolean ok = s.equals(want) || close(s, want);
        if (!ok) {
            bad++;
        }
        System.out.println((ok ? "PASS #" : "FAIL #") + n + "  " + s + (ok ? "" : "   want " + want));
    }

    /** Print the tally; exit non-zero so `leet.py run` and shell pipelines see the failure. */
    public void done() {
        System.out.println((n - bad) + "/" + n + " passed");
        if (bad > 0) {
            System.exit(1);
        }
    }

    /** LeetCode grades floating point to 1e-5, so do the same instead of string-matching. */
    private static boolean close(String a, String b) {
        try {
            return Math.abs(Double.parseDouble(a) - Double.parseDouble(b)) < 1e-5;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    /** Render any result the way leet.py renders the expected value: no quotes, no separator spaces. */
    private static String show(Object o) {
        String s;
        if (o instanceof int[]) {
            s = Arrays.toString((int[]) o);
        } else if (o instanceof long[]) {
            s = Arrays.toString((long[]) o);
        } else if (o instanceof double[]) {
            s = Arrays.toString((double[]) o);
        } else if (o instanceof boolean[]) {
            s = Arrays.toString((boolean[]) o);
        } else if (o instanceof char[]) {
            s = Arrays.toString((char[]) o);
        } else if (o instanceof Object[]) {
            s = Arrays.deepToString((Object[]) o);
        } else {
            s = String.valueOf(o);
        }
        return s.replace(", ", ",");
    }
}
